    "employeeNumber": {
      "type": "string",
      "description": "Unique identifier for the employee."
    },
    "qualificationTypeId": {
      "type": "string",
      "description": "The ID representing the selected Qualification Type (e.g., Postgraduate Degree). This value is derived from user selection after displaying the available types from 'getEducationalAndProfessionalQualificationsDetails'. The user is not asked to provide this ID directly."
    },
    "qualificationId": {
      "type": "string",
      "description": "The specific ID of the selected qualification (e.g., MBA, BSc). This is selected by the user from the options shown, which are fetched after the Qualification Type is selected. The user is not expected to know or input the ID directly."
    },
    "qualificationEffectStartDate": {
      "type": "string",
      "format": "date",
      "description": "'qualificationEffectStartDate' The qualification effect start date must strictly follow the 'm/d/YYYY' format and should be captured before calling the final API. the 'getEducationalAndProfessionalQualificationsDetails' should be used. Additionally, the AI must not generate any random dates during this process."
    },
    "qualificationEffectEndDate": {
      "type": "string",
      "format": "date",
      "description": "'qualificationEffectEndDate' The qualification effect end date must strictly follow the 'm/d/YYYY' format and should be captured before calling the final API. the 'getEducationalAndProfessionalQualificationsDetails' should be used. Additionally, the AI must not generate any random dates during this process."
    },
    "institutionName": {
      "type": "string",
      "description": "Name of the school or institution from which the qualification was obtained."
    },
    "qualificationStatus": {
      "type": "string",
      "enum": ["0", "1", "2", "3", "4", "5"],
      "description": "Status of the qualification. Options are sourced from 'getEducationalAndProfessionalQualificationsDetails' and may include: 0: Pass, 1: First Class, 2: Second Class, etc."
    },
    "jobRelated": {
      "type": "string",
      "enum": ["0", "1"],
      "description": "Indicates whether the qualification is job-related. Values: 0 = No, 1 = Yes. Options are provided via 'getEducationalAndProfessionalQualificationsDetails'."
    },
    "durationValue": {
      "type": "string",
      "description": "Numeric value representing the duration of the qualification (e.g., 4.00)."
    },
    "durationType": {
      "type": "string",
      "enum": ["000001", "000002", "000003", "000004", "000005"],
      "description": "Type of duration. Values include: 000001 = Years, 000002 = Months, 000003 = Weeks, 000004 = Days, 000005 = Hours. These options are fetched from 'getEducationalAndProfessionalQualificationsDetails'."
    },
    "yearOfPassing": {
      "type": "string",
      "description": "Year in which the qualification was obtained (e.g., 2023)."
    },
    "comments": {
      "type": "string",
      "description": "Any additional comments or notes regarding the qualification."
    },
    "totalCost": {
      "type": "string",
      "description": "Total cost incurred for completing the qualification. dont take dynamic amount"
    },
    "currencyForTotalCost": {
      "type": "string",
      "description": "Currency code for the total cost. The list of currencies is shown to the user, and the corresponding selected value is used. These values are fetched from 'getEducationalAndProfessionalQualificationsDetails'. dont take dynamic currency you get before api data get."
