    },
    "reimbursementEffectDate": {
      "type": "string",
      "format": "date",
      "description": "The end date of the qualification (format: YYYY-MM-DD). dont take dynamic effect data you get before api data get."
    }
  },
  "required": [
    "employeeNumber",
    "qualificationTypeId",
    "qualificationId",
    "institutionName",
    "qualificationStatus",
    "durationType",
    "yearOfPassing",
    "qualificationEffectStartDate",
    "qualificationEffectEndDate"
  ]
}

